MATCH (x:PlateHeatExchanger:PlantItem {unit_id: '36'})
RETURN x.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'EJ-401B'}), (b:PlantItem {tag: 'EJ-402A'})
RETURN EXISTS {
  MATCH (a)-[:line_to*1..]->(b)
  WHERE NOT EXISTS {
    MATCH (a)-[:line_to*1..]->(e:PlantItem {tag: 'E-403'})-[:line_to*1..]->(b)
  }
} AS can_flow_without_E403

MATCH (:PlantItem {tag: 'P-4601'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (target:PlantItem {tag: 'V-3701'})-[:line_to]-(v:Valve)<-[:control]-(act:ActuatingFunction)<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'E-2701'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'M-4201'}), (b:PlantItem {tag: 'V-4201'}), (v:PlantItem:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (:PlantItem {tag: 'T-4001'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'P-4601'}), (b:PlantItem {tag: 'TK-4602'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'H-4301'}), (b:PlantItem {tag: 'E-4301'}), (r:PlantItem {tag: 'R-4301'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> r AND y <> r)+ (b)
}
RETURN b.tag AS tag
ORDER BY tag

MATCH (loop:ProcessControlFunction {loop_tag: 'FIC-40072'})-[:send_signal_to*1..]->(act:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'V-3001'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet
ORDER BY sheet;

MATCH (a:PlantItem {tag: 'K-3801'}), (b:PlantItem {tag: 'F-3801'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'EA-3801')* (b)
} AS reachable_without_EA-3801

MATCH (a:PlantItem {tag: 'K-3801'}), (b:PlantItem {tag: 'F-3801'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'EA-3801')* (b)
} AS reachable_without_EA_3801

MATCH (a:PlantItem {tag: 'F-201A'}), (b:PlantItem {tag: 'V-301'}), (v:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-3701C'}), (e:PlantItem {tag: 'E-3901'}), (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN count(DISTINCT v.tag) AS valve_count, collect(DISTINCT v.tag) AS valve_tags

MATCH (a:PlantItem {tag: 'T-2701'}), (b:PlantItem {tag: 'TK-2802'}), (blocked:PlantItem {tag: 'P-2701A'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> blocked AND y <> blocked)+ (b)
       } AS reachable_without_P2701A

MATCH (v:PlantItem:PressureVessel {unit_id: '4'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-4501C'}), (b:PlantItem {tag: 'E-4701'})
MATCH (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v.tag) AS valve_count, collect(DISTINCT v.tag) AS valve_tags

MATCH (p:PlantItem {tag: 'P-3701C'}), (e:PlantItem {tag: 'E-3901'})
CALL {
  WITH p
  MATCH (p)-[:line_to*1..]->(v:Valve)
  RETURN collect(DISTINCT v) AS downstream_valves
}
CALL {
  WITH e
  MATCH (v:Valve)-[:line_to*1..]->(e)
  RETURN collect(DISTINCT v) AS upstream_valves
}
WITH [v IN downstream_valves WHERE v IN upstream_valves | v.tag] AS valve_tags
RETURN size(valve_tags) AS valve_count, valve_tags AS valve_tags

MATCH (a:PlantItem {tag: 'P-502'}), (b:PlantItem {tag: 'P-601A'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'TK-1004'}), (b:PlantItem {tag: 'P-1101B'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE x.tag <> 'P-1001A' AND y.tag <> 'P-1001A')+ (b)
       } AS reachable_without_P_1001A

MATCH (a:PlantItem {tag: 'E-3301'}), (b:PlantItem {tag: 'P-3401C'})
RETURN EXISTS {
  (a)-[:line_to*1..]->(b)
  WHERE NONE(v IN [(a)-[:line_to*0..]->(x:PlantItem)-[:line_to*0..]->(b) | x] WHERE v.tag = 'YV-34001')
} AS reachable_without_YV_34001

MATCH (a:PlantItem {tag: 'EA-501'}), (b:PlantItem {tag: 'P-601B'})
MATCH p = shortestPath((a)-[:line_to*]->(b))
RETURN [n IN nodes(p) WHERE n:Valve | n.tag] AS valve_tags \;

MATCH (a:PlantItem {tag: 'P-301C'}), (b:PlantItem {tag: 'EA-701'})
RETURN a.tag AS source_tag, b.tag AS target_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'T-2101'}), (b:PlantItem {tag: 'T-2701'}), (excluded:PlantItem {tag: 'E-2102'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y <> excluded){1,} (b)
       } AS reachable

MATCH (r:PlantItem {tag: 'R-3701'}), (t:PlantItem {tag: 'T-4401'}), (v:Valve)
WHERE EXISTS { (r)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(t) }
RETURN count(DISTINCT v.tag) AS valve_count

MATCH (a:PlantItem {tag: 'P-701B'}), (b:PlantItem {tag: 'V-1101'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE y.tag <> 'YV-8012')+ (b)
       } AS reachable_without_YV_8012

MATCH (a:PlantItem {tag: 'P-2001A'}), (b:PlantItem {tag: 'P-3901B'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-801B'}), (b:PlantItem {tag: 'P-3001C'}), (excluded:PlantItem {tag: 'P-2702A'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem WHERE x <> excluded)-[:line_to]->(y:PlantItem WHERE y <> excluded)){1,} (b)
       } AS can_flow_without_excluded_tag

MATCH (a:PlantItem {tag: 'V-301'}), (b:PlantItem {tag: 'P-4601'}), (v:PlantItem:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (item:PlantItem {tag: 'YV-13005'})
RETURN item.tag AS tag, labels(item) AS item_type
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(p:PlantItem {tag: 'P-901B'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(a:PlantItem {tag: 'EA-1501'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'V-1601'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(a:PlantItem {tag: 'EA-4401'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(e:PlantItem {tag: 'E-501'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;
